import uuid
from datetime import datetime

from sqlalchemy import (
    Boolean,
    CheckConstraint,
    Computed,
    DateTime,
    ForeignKey,
    Index,
    SmallInteger,
    String,
    Text,
    UniqueConstraint,
    text,
)
from sqlalchemy.dialects.postgresql import ARRAY, TSVECTOR, UUID
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.db.base import Base, Timestamps, UUIDPrimaryKey, enum_check, slug_check, url_check
from app.models.enums import ContentStatus, Topic

# Weighted keyword index: title > summary > body. Generated by PostgreSQL, never written by the app.
SEARCH_VECTOR_SQL = (
    "setweight(to_tsvector('english', coalesce(title, '')), 'A') || "
    "setweight(to_tsvector('english', coalesce(summary, '')), 'B') || "
    "setweight(to_tsvector('english', coalesce(content, '')), 'C')"
)


class Story(UUIDPrimaryKey, Timestamps, Base):
    __tablename__ = "stories"
    __table_args__ = (
        slug_check(),
        enum_check("topic", Topic),
        enum_check("status", ContentStatus),
        url_check("original_url"),
        url_check("image_url"),
        CheckConstraint("(original_url IS NULL) = (canonical_url IS NULL)", name="canonical_url_pairs"),
        CheckConstraint("reading_time_minutes BETWEEN 1 AND 120", name="reading_time_range"),
        CheckConstraint("edition_position IS NULL OR edition_position > 0", name="edition_position_positive"),
        CheckConstraint(
            "(image_url IS NULL AND image_alt IS NULL AND image_credit IS NULL) OR "
            "(image_url IS NOT NULL AND image_alt IS NOT NULL AND image_credit IS NOT NULL)",
            name="image_complete",
        ),
        # A published story must be fully attributed and complete enough to render.
        CheckConstraint(
            "status <> 'published' OR (published_at IS NOT NULL AND source_id IS NOT NULL "
            "AND impact_why_it_matters IS NOT NULL AND impact_build_idea IS NOT NULL)",
            name="published_complete",
        ),
        UniqueConstraint("edition_id", "edition_position"),
        Index("ix_stories_one_featured_per_edition", "edition_id", unique=True, postgresql_where=text("is_featured")),
        Index("ix_stories_public", "status", "published_at"),
        Index("ix_stories_search_vector", "search_vector", postgresql_using="gin"),
        Index("ix_stories_tags", "tags", postgresql_using="gin"),
    )

    slug: Mapped[str] = mapped_column(String(160), unique=True)
    title: Mapped[str] = mapped_column(String(300))
    summary: Mapped[str] = mapped_column(Text)
    # Paragraphs separated by a blank line; the API returns them as a list.
    content: Mapped[str] = mapped_column(Text, default="", server_default="")
    topic: Mapped[str] = mapped_column(String(16), index=True)
    tags: Mapped[list[str]] = mapped_column(ARRAY(Text), default=list, server_default="{}")
    status: Mapped[str] = mapped_column(String(16), default=ContentStatus.DRAFT, server_default="draft")
    is_demo: Mapped[bool] = mapped_column(Boolean, default=False, server_default="false")
    is_featured: Mapped[bool] = mapped_column(Boolean, default=False, server_default="false")

    edition_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("editions.id", ondelete="RESTRICT"), index=True
    )
    edition_position: Mapped[int | None] = mapped_column(SmallInteger)

    source_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("sources.id", ondelete="RESTRICT"), index=True
    )
    original_url: Mapped[str | None] = mapped_column(Text)
    # original_url after canonicalisation (app.services.urls); the duplicate-article guard.
    canonical_url: Mapped[str | None] = mapped_column(Text, unique=True)
    original_published_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    published_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    reading_time_minutes: Mapped[int] = mapped_column(SmallInteger, default=3, server_default="3")

    image_url: Mapped[str | None] = mapped_column(Text)
    image_alt: Mapped[str | None] = mapped_column(Text)
    image_credit: Mapped[str | None] = mapped_column(Text)

    impact_why_it_matters: Mapped[str | None] = mapped_column(Text)
    impact_explore: Mapped[list[str]] = mapped_column(ARRAY(Text), default=list, server_default="{}")
    impact_build_idea: Mapped[str | None] = mapped_column(Text)
    impact_disciplines: Mapped[list[str]] = mapped_column(ARRAY(Text), default=list, server_default="{}")

    search_vector = mapped_column(TSVECTOR, Computed(SEARCH_VECTOR_SQL, persisted=True), nullable=True)

    edition = relationship("Edition", back_populates="stories")
    source = relationship("Source")
